import { useRef } from 'react';
import { Button, useToaster } from '@gravity-ui/uikit';

const AUTO_HIDE_MS = 4000;

export function NotifyButton() {
  const { add } = useToaster();
  const counter = useRef(0);

  const handleClick = () => {
    counter.current += 1;
    add({
      // Unique name per click so repeated clicks stack new toasts instead of updating one
      name: `notification-${counter.current}`,
      title: 'Уведомление',
      content: 'Это всплывающее уведомление исчезнет автоматически.',
      theme: 'success',
      autoHiding: AUTO_HIDE_MS,
    });
  };

  return (
    <Button view="action" size="l" onClick={handleClick}>
      Показать уведомление
    </Button>
  );
}
EOF
cat > src/App.tsx <<'EOF'
import { Box, Toaster, ToasterComponent, ToasterProvider } from '@gravity-ui/uikit';

import { NotifyButton } from './NotifyButton';

// A single toaster instance shared by the whole app
const toaster = new Toaster();

export function App() {
  return (
    <ToasterProvider toaster={toaster}>
      <Box spacing={{ p: 6 }}>
        <NotifyButton />
      </Box>
      {/* Renders the toast stack in the corner of the screen */}
      <ToasterComponent />
    </ToasterProvider>
  );
}
EOF
